func (q *Queries) ProspectTaxIDMatches(ctx context.Context, arg ProspectTaxIDMatchesParams) ([]ProspectTaxIDMatchesRow, error) {
	rows, err := q.db.Query(ctx, prospectTaxIDMatches, arg.AfterProspectID, arg.AfterStoreID, arg.PageSize)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ProspectTaxIDMatchesRow{}
	for rows.Next() {
		var i ProspectTaxIDMatchesRow
		if err := rows.Scan(
			&i.ProspectID,
			&i.StoreID,
			&i.StoreName,
			&i.CompanyName,
			&i.KycStatus,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

