const repointDistinctPairs = `-- name: RepointDistinctPairs :exec
INSERT INTO seller.prospect_distinct_pairs (low_prospect_id, high_prospect_id, confirmed_by_admin_id, confirmed_at)
SELECT LEAST($1::bigint, m.other_id), GREATEST($1::bigint, m.other_id), m.confirmed_by_admin_id, m.confirmed_at
FROM (
    SELECT CASE WHEN low_prospect_id = $2::bigint THEN high_prospect_id ELSE low_prospect_id END AS other_id,
           confirmed_by_admin_id, confirmed_at
    FROM seller.prospect_distinct_pairs
    WHERE low_prospect_id = $2::bigint OR high_prospect_id = $2::bigint
) m
WHERE m.other_id <> $1::bigint
ON CONFLICT DO NOTHING
`

type RepointDistinctPairsParams struct {
	WinnerID int64
	LoserID  int64
}

// 合併：輸家的「不是同一家」配對改掛贏家；與贏家自己的那一對（變成自己對自己）不搬，已有的略過。
func (q *Queries) RepointDistinctPairs(ctx context.Context, arg RepointDistinctPairsParams) error {
	_, err := q.db.Exec(ctx, repointDistinctPairs, arg.WinnerID, arg.LoserID)
	return err
}

